health = {("gemini-flash", "us-central1"): False, ("gemini-flash", "global"): False, ("gpt-5", "us"): True}
ROUTES = {"gemini-flash": ["us-central1", "global"]}
FALLBACK = {"gemini-flash": ("gpt-5", "us")}
breaker, OPEN_AT = {}, 3

class Down(Exception): pass

def call(model, region):
    if not health[(model, region)]:
        raise Down(f"{model}@{region}")
    return f"ok from {model}@{region}"

def route(model, retries=2):
    if breaker.get(model, 0) >= OPEN_AT:
        return "[breaker open] " + call(*FALLBACK[model])
    for region in ROUTES[model]:
        for i in range(retries):
            try:
                out = call(model, region); breaker[model] = 0; return out
            except Down:
                pass  # 실제로는 2**i 초씩 늘려 기다린다
    breaker[model] = breaker.get(model, 0) + 1
    return "[model fallback] " + call(*FALLBACK[model])

for n in range(5):
    print(n + 1, route("gemini-flash"), "| fails:", breaker["gemini-flash"])
# 1 [model fallback] ok from gpt-5@us | fails: 1
# 2 [model fallback] ok from gpt-5@us | fails: 2
# 3 [model fallback] ok from gpt-5@us | fails: 3
# 4 [breaker open] ok from gpt-5@us | fails: 3
# 5 [breaker open] ok from gpt-5@us | fails: 3

user = {"read:posts", "read:reports", "write:reports"}
agent = {"read:reports", "write:reports", "delete:posts"}
granted = user & agent
for want in ("write:reports", "delete:posts", "read:posts"):
    print(want, "->", "allow" if want in granted else "deny")
# write:reports -> allow
# delete:posts -> deny
# read:posts -> deny
